628: function startBattle(node) {
629:   const run = state.run;
630:   const key = chooseEnemySpecies(node);
631:   const sp = SPECIES[key];
632:   const isElite = node.type === 'elite';
633:   const isBoss = node.type === 'boss';
634:   let hp = Math.round(sp.baseHp * (1 + node.row * .012));
635:   if (node.type === 'grass') hp = Math.max(12, Math.round(hp * .55));
636:   if (isBoss) hp = sp.baseHp;
637:   if (isElite) hp = Math.round(sp.baseHp * 1.06);
638: 
639:   const enemy = {
640:     key, name: sp.name, types: sp.types, maxHp: hp, hp, block: 0,
641:     statuses: { poison: 0, burn: 0, weak: 0, vulnerable: 0 },
642:     strength: 0, moveIndex: 0, intent: null,
643:     level: 3 + node.row, isElite, isBoss, flavor: sp.flavor
644:   };
645:   const player = {
646:     block: 0, statuses: { poison: 0, burn: 0, weak: 0, vulnerable: 0 },
647:     energy: 3, maxEnergy: 3, strength: 0
648:   };
649:   if (hasRelic('choice_band')) player.strength += 2;
650:   if (hasRelic('bicycle')) player.energy += 1;
651: 
652:   const battle = {
653:     node, speciesKey: key, enemy, player,
654:     hand: [], drawPile: shuffle(run.deck.map(c => ({ ...c }))), discardPile: [], exhaustPile: [],
655:     turn: 1, busy: false, over: false, focusUsed: false, bossPhase: false,
656:     catchBonus: node.type === 'grass' ? 12 : 0,
657:     lastLog: null, rewards: null
658:   };
659:   state.battle = battle;
660:   state.node = node;
661:   run.battles++;
662:   enemy.intent = getEnemyIntent(battle);
663:   setScreen('battle');
664:   $('#screen-battle')?.classList.toggle('boss-fight', isBoss);
665:   drawCards(5 + drawBonus());
666:   renderBattle();
667:   renderHand();
668:   const intro = isBoss ? 'The air turns to glass. Mewtwo descends.' :
669:     node.type === 'grass' ? `Something rustles in the tall grass... ${sp.name} appears, already weary.` :
670:     isElite ? `An elite ${sp.name} blocks the way!` :
671:     `A wild ${sp.name} appears!`;
672:   logBattle(intro);
673:   if (isBoss) toast('The Spire Heart awakens.', 'bad', 3200);
674:   if (node.type === 'grass') toast('It is already weakened — catch odds improved.', 'good');
675:   if (key === 'mew') { toast('A rare shimmer... Mew!', 'good', 3600); fxBanner('A RARE SHIMMER'); }
676: }
