738: function statusPills(statuses, strength = 0) {
739:   const list = [];
740:   const map = [
741:     ['poison', 'Poison', '☠'], ['burn', 'Burn', '♨'], ['weak', 'Weak', '↓'], ['vulnerable', 'Vuln', '◇']
742:   ];
743:   for (const [k, label, glyph] of map) {
744:     if (statuses?.[k] > 0) list.push(`<span class="status-pill ${k}">${glyph} ${label} <b>${statuses[k]}</b></span>`);
745:   }
746:   if (strength > 0) list.push(`<span class="status-pill strength">↑ Str <b>${strength}</b></span>`);
747:   return list.join('');
748: }
