.mon-3{animation:bob 4.1s 1s ease-in-out infinite}
@keyframes bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-9px)}}
.title-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.title-features{display:flex;gap:22px;margin-top:30px;font-size:11px;letter-spacing:.06em;color:var(--muted);text-transform:uppercase}
.title-features b{color:var(--gold-2);font-weight:600;margin-right:2px}
.title-footer{
  position:absolute;left:8vw;right:4vw;bottom:calc(18px + var(--safe-bottom));z-index:4;
  display:flex;align-items:center;gap:12px;color:rgba(180,195,178,.55);font-size:10px;letter-spacing:.05em;
}
.footer-dot{width:3px;height:3px;border-radius:50%;background:var(--gold);opacity:.5}
.title-footer .icon-btn{width:auto;height:auto;border:0;background:none;font-size:10px;letter-spacing:.05em;padding:0;color:rgba(180,195,178,.55)}
.title-footer .icon-btn:hover{color:var(--gold-2);background:none}

/* ============================================================
   HUD
   ============================================================ */
#hud{
  position:fixed;left:0;right:0;top:0;height:calc(66px + var(--safe-top));z-index:50;
  padding:var(--safe-top) 18px 0;
  display:grid;grid-template-columns:190px 1fr auto;align-items:center;gap:18px;
  background:linear-gradient(180deg,rgba(8,18,14,.95),rgba(8,18,14,.78));
  border-bottom:1px solid rgba(217,183,109,.16);
  backdrop-filter:blur(16px);
}
.hud-brand{display:flex;align-items:center;gap:10px;font-family:'Cinzel',serif;font-size:15px;letter-spacing:.1em;color:var(--cream);text-align:left}
.hud-brand em{font-style:normal;color:var(--gold)}
.brand-rune{display:flex;align-items:center;justify-content:center;width:28px;height:28px;border-radius:50%;border:1px solid rgba(217,183,109,.4);color:var(--gold);font-size:13px;background:rgba(217,183,109,.08)}
.hud-stats{display:flex;align-items:center;justify-content:center;gap:10px}
.hud-hp{width:220px}
.hud-hp-top{display:flex;justify-content:space-between;font-size:8px;letter-spacing:.14em;color:var(--muted);margin-bottom:3px}
.hud-hp-top b{font-size:10px;color:var(--cream);letter-spacing:.02em}
.hud-hp-track{height:7px;border-radius:4px;background:rgba(0,0,0,.45);overflow:hidden;border:1px solid rgba(255,255,255,.06)}
.hud-hp-fill{height:100%;width:100%;border-radius:4px;background:linear-gradient(90deg,#4f9f6b,#82d39b);transition:width .35s ease}
.hud-hp-fill.low{background:linear-gradient(90deg,#a34a37,#d97054)}
.hud-pill{display:flex;align-items:center;gap:6px;padding:6px 10px;border:1px solid var(--line);border-radius:999px;background:rgba(18,40,31,.65);font-size:12px;color:var(--cream);min-height:31px}
.hud-pill b{font-weight:600;font-variant-numeric:tabular-nums}
.hud-floor b{color:var(--gold-2)}
.hud-actions{display:flex;align-items:center;gap:6px}
.hud-btn{
  display:flex;align-items:center;gap:6px;padding:7px 10px;border:1px solid var(--line);border-radius:8px;
  font-size:10px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);background:rgba(18,40,31,.5);transition:.2s;
}
.hud-btn b{color:var(--gold-2);font-size:11px}
.hud-btn:hover{color:var(--cream);border-color:var(--line-strong);background:rgba(32,66,51,.6)}
.hud-btn-icon{width:33px;justify-content:center;font-size:14px;padding:7px 0}
.sound-off{opacity:.55}

/* ============================================================
   Map
   ============================================================ */
.map-screen{
  background:
    radial-gradient(ellipse at 50% 0%,rgba(67,113,84,.2),transparent 48%),
    radial-gradient(ellipse at 12% 70%,rgba(44,91,66,.14),transparent 42%),
    linear-gradient(180deg,#0c1a15,#09130f 60%,#07100d);
}
.map-layout{height:calc(100dvh - 66px);display:grid;grid-template-columns:minmax(0,1fr) 304px;gap:18px;padding:14px 18px 18px;max-width:1500px;margin:0 auto}
.map-main{display:flex;flex-direction:column;min-width:0;min-height:0}
.map-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;padding:4px 8px 10px;flex:0 0 auto}
.map-heading h2{font-size:clamp(22px,2.3vw,32px);margin-top:5px}
.map-legend{display:flex;gap:14px;font-size:10px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted);padding-bottom:4px}
.map-legend span{display:flex;align-items:center;gap:5px}
.legend-dot{width:6px;height:6px;border-radius:50%;display:inline-block}
.legend-dot.wild{background:var(--green)}.legend-dot.elite{background:var(--red)}.legend-dot.camp{background:var(--gold)}
.map-viewport{position:relative;flex:1;min-height:0;overflow:auto;border:1px solid rgba(217,183,109,.15);border-radius:16px;background:linear-gradient(180deg,rgba(20,42,33,.62),rgba(8,19,15,.72));box-shadow:inset 0 0 100px rgba(0,0,0,.4);scrollbar-width:thin;scrollbar-color:#365748 transparent;overscroll-behavior:contain}
.map-viewport::-webkit-scrollbar{width:6px}
.map-viewport::-webkit-scrollbar-thumb{background:#365748;border-radius:4px}
.map-scroll{position:relative;height:980px;min-width:420px;overflow:hidden}
.map-scroll::before{
  content:"";position:absolute;inset:0;
  background:
    radial-gradient(ellipse at 50% 8%,rgba(220,211,163,.14),transparent 16%),
    repeating-linear-gradient(120deg,rgba(255,255,255,.012) 0 1px,transparent 1px 9px),
    radial-gradient(ellipse at 50% 100%,rgba(38,83,60,.3),transparent 50%);
  pointer-events:none;
}
.map-fog{position:absolute;width:80%;height:160px;left:10%;border-radius:50%;filter:blur(34px);background:rgba(145,183,154,.06);pointer-events:none;animation:fogDrift 16s ease-in-out infinite alternate}
.map-fog-a{top:18%}.map-fog-b{top:62%;animation-delay:-8s;width:60%;left:2%}
@keyframes fogDrift{from{transform:translateX(-4%) scale(1)}to{transform:translateX(6%) scale(1.1)}}
.map-lines{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}
.map-lines path{fill:none;stroke:rgba(126,159,132,.2);stroke-width:1.4;vector-effect:non-scaling-stroke}
.map-lines path.route{stroke:rgba(217,183,109,.72);stroke-width:2;filter:drop-shadow(0 0 5px rgba(217,183,109,.45))}
.map-lines path.available{stroke:rgba(151,207,157,.42);stroke-width:1.8;stroke-dasharray:4 5}
.map-nodes{position:absolute;inset:0}
.map-node{
  position:absolute;width:56px;height:56px;transform:translate(-50%,-50%);
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  border-radius:50%;border:1px solid rgba(194,216,184,.18);
  background:linear-gradient(180deg,rgba(31,63,48,.92),rgba(12,29,22,.96));
  color:var(--muted);box-shadow:0 8px 18px rgba(0,0,0,.32),inset 0 1px 0 rgba(255,255,255,.06);
  transition:transform .2s,border-color .2s,box-shadow .2s,filter .2s;
  z-index:2;
}
.map-node svg{width:23px;height:23px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.map-node .node-floor{position:absolute;bottom:-16px;font-size:8px;letter-spacing:.12em;color:var(--muted-2);opacity:.8}
.map-node.locked{filter:grayscale(.7);opacity:.34;cursor:default}
.map-node.available{cursor:pointer;border-color:rgba(217,183,109,.75);color:var(--gold-2);box-shadow:0 0 0 4px rgba(217,183,109,.06),0 0 24px rgba(217,183,109,.22),inset 0 1px 0 rgba(255,255,255,.12);animation:nodePulse 2.6s ease-in-out infinite}
.map-node.available:hover{transform:translate(-50%,-50%) scale(1.12);border-color:#ffe7a8;box-shadow:0 0 0 5px rgba(217,183,109,.1),0 0 32px rgba(217,183,109,.38)}
.map-node.visited{opacity:.72;border-color:rgba(115,164,128,.4);color:#8ab394}
.map-node.current{border-color:var(--gold-2);color:var(--gold-2);box-shadow:0 0 0 5px rgba(217,183,109,.13),0 0 30px rgba(217,183,109,.3)}
.map-node.type-elite{color:#e6a39a}.map-node.type-elite.available{color:#f2b3aa;border-color:rgba(216,98,88,.7);box-shadow:0 0 0 4px rgba(216,98,88,.08),0 0 28px rgba(216,98,88,.24);animation:elitePulse 2s ease-in-out infinite}
.map-node.type-boss{width:68px;height:68px;color:#ddb8ee;border-color:rgba(177,129,210,.6);background:linear-gradient(180deg,rgba(58,36,74,.95),rgba(20,13,30,.98));box-shadow:0 0 32px rgba(177,129,210,.18)}
.map-node.type-boss svg{width:30px;height:30px}
.map-node.type-camp{color:#e5c785}.map-node.type-shop{color:#9bc5df}.map-node.type-treasure{color:#e5c56f}.map-node.type-grass{color:#8bd29a}
.map-node.type-start{width:44px;height:44px;border-style:dashed;color:var(--muted)}
@keyframes nodePulse{0%,100%{box-shadow:0 0 0 4px rgba(217,183,109,.05),0 0 18px rgba(217,183,109,.18),inset 0 1px 0 rgba(255,255,255,.1)}50%{box-shadow:0 0 0 6px rgba(217,183,109,.1),0 0 30px rgba(217,183,109,.3),inset 0 1px 0 rgba(255,255,255,.1)}}
@keyframes elitePulse{0%,100%{box-shadow:0 0 0 4px rgba(216,98,88,.07),0 0 20px rgba(216,98,88,.18)}50%{box-shadow:0 0 0 7px rgba(216,98,88,.13),0 0 34px rgba(216,98,88,.33)}}
.map-node .node-badge{position:absolute;top:-6px;right:-6px;width:16px;height:16px;border-radius:50%;background:var(--gold);color:#1b1509;display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700;border:1px solid #2a2110}
.map-side{display:flex;flex-direction:column;gap:10px;min-height:0;overflow:auto;scrollbar-width:none}
.map-side::-webkit-scrollbar{display:none}
.side-card{background:linear-gradient(160deg,rgba(26,53,42,.75),rgba(11,27,21,.86));border:1px solid rgba(217,183,109,.14);border-radius:13px;padding:13px;box-shadow:0 10px 30px rgba(0,0,0,.16)}
.side-run-top{display:flex;gap:12px;align-items:center;margin:10px 0 13px}
.side-portrait{width:54px;height:54px;border-radius:12px;background:radial-gradient(circle at 50% 65%,rgba(104,158,120,.24),rgba(8,20,15,.5));border:1px solid rgba(255,255,255,.08);display:flex;align-items:center;justify-content:center}
.side-portrait img{width:46px;height:46px;object-fit:contain;image-rendering:pixelated}
.side-run h3{font-family:'Cinzel',serif;font-size:19px;margin-bottom:2px}
.type-line{font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:var(--muted)}
.side-level{font-size:10px;color:var(--muted-2);margin-top:3px}
.side-level b{color:var(--gold-2)}
.side-stat-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.side-stat-grid div{background:rgba(5,15,11,.35);border:1px solid rgba(255,255,255,.05);border-radius:8px;padding:6px 8px;display:flex;justify-content:space-between;align-items:center}
.side-stat-grid span{font-size:9px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted-2)}
.side-stat-grid b{font-size:12px;color:var(--cream)}
.side-card-title{display:flex;justify-content:space-between;align-items:center;font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-bottom:9px}
.side-card-title span:last-child{color:var(--gold-2);letter-spacing:.04em}
.side-party-row{display:flex;gap:6px;flex-wrap:wrap;min-height:42px}
.party-chip{width:38px;height:38px;border-radius:9px;border:1px solid rgba(255,255,255,.08);background:rgba(7,18,13,.5);display:flex;align-items:center;justify-content:center;position:relative}
.party-chip img{width:32px;height:32px;image-rendering:pixelated}
.party-chip.empty{border-style:dashed;opacity:.35;font-size:12px;color:var(--muted)}
.side-ball-row{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}
.ball-mini{display:flex;flex-direction:column;align-items:center;gap:4px;padding:7px 4px;border-radius:8px;background:rgba(5,15,11,.35);border:1px solid rgba(255,255,255,.05)}
.ball-mini .ball-icon{width:18px;height:18px}
.ball-mini span{font-size:8px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted-2)}
.ball-mini b{font-size:12px;color:var(--cream)}
.side-relic-row{display:flex;gap:6px;flex-wrap:wrap;min-height:31px}
.relic-chip{width:30px;height:30px;border-radius:50%;border:1px solid rgba(217,183,109,.3);background:radial-gradient(circle at 35% 30%,rgba(244,219,150,.15),rgba(8,20,15,.8));display:flex;align-items:center;justify-content:center;font-size:14px;color:var(--gold-2);cursor:help}
.side-tip{display:flex;gap:9px;padding:10px 12px;border-radius:10px;border:1px dashed rgba(217,183,109,.18);background:rgba(217,183,109,.04);font-size:10px;line-height:1.4;color:var(--muted)}
.side-tip p{font-size:10px;color:var(--muted)}
.tip-spark{color:var(--gold);font-size:12px;line-height:1.2}

/* ============================================================
   Battle
   ============================================================ */
.battle-screen{
  display:flex;flex-direction:column;overflow:clip;padding:calc(66px + var(--safe-top)) 16px 8px;
  background:#07100d;
}
.battle-bg{position:absolute;inset:0;background:url('../assets/bg/forest.svg') center/cover no-repeat;z-index:-2;transform:scale(1.02)}
.battle-bg::after{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 50% 52%,transparent 15%,rgba(2,8,6,.5) 85%),linear-gradient(180deg,rgba(2,8,6,.28),transparent 25%,rgba(2,8,6,.68))}
.battle-moon{position:absolute;right:16%;top:6%;width:120px;height:120px;border-radius:50%;background:radial-gradient(circle at 40% 35%,rgba(239,237,205,.65),rgba(199,210,171,.15) 60%,transparent 70%);filter:blur(1px)}
.battle-trees{position:absolute;bottom:0;width:26%;height:80%;background:linear-gradient(180deg,transparent,#06100c);opacity:.55;filter:blur(1px)}
.trees-left{left:-4%;clip-path:polygon(0 100%,0 30%,15% 48%,20% 20%,34% 47%,46% 10%,60% 42%,74% 22%,100% 55%,100% 100%)}
.trees-right{right:-4%;transform:scaleX(-1);clip-path:polygon(0 100%,0 30%,15% 48%,20% 20%,34% 47%,46% 10%,60% 42%,74% 22%,100% 55%,100% 100%)}
.battle-mist{position:absolute;left:-10%;right:-10%;height:70px;border-radius:50%;background:rgba(175,201,171,.07);filter:blur(20px);animation:mistMove 18s linear infinite}
.mist-a{bottom:23%}.mist-b{bottom:12%;animation-duration:24s;animation-direction:reverse}
@keyframes mistMove{from{transform:translateX(-5%)}to{transform:translateX(5%)}}
.battle-topline{position:relative;z-index:5;display:flex;align-items:center;gap:8px;height:32px;flex:0 0 auto}
.battle-chip{padding:4px 10px;border-radius:999px;border:1px solid rgba(255,255,255,.1);background:rgba(5,16,12,.55);backdrop-filter:blur(8px);font-size:9px;letter-spacing:.11em;text-transform:uppercase;color:var(--muted)}
.battle-turn{color:var(--cream)}
.battle-energy{display:flex;align-items:center;gap:6px;color:var(--gold-2)}
.battle-energy .energy-orb{width:17px;height:17px;font-size:9px}
.battle-help{margin-left:auto;width:26px;height:26px;font-size:11px}
.battle-stage{position:relative;flex:1 1 auto;min-height:240px;max-height:390px;z-index:2}
.combatant{position:absolute;bottom:0;width:46%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:flex-end}
.player-combatant{left:2%}
.enemy-combatant{right:2%}
.platform{
  position:absolute;bottom:92px;width:min(250px,62%);height:44px;border-radius:50%;
  background:radial-gradient(ellipse,rgba(116,160,124,.22),rgba(7,18,13,.04) 66%);
  border:1px solid rgba(176,207,173,.12);transform:perspective(200px) rotateX(60deg);
  box-shadow:0 0 40px rgba(139,190,146,.08);
}
.platform::after{content:"";position:absolute;inset:8px 16px;border-radius:50%;border:1px solid rgba(217,183,109,.12)}
.mon-wrap{position:absolute;bottom:92px;display:flex;align-items:flex-end;justify-content:center;transition:transform .18s}
.combat-mon{width:clamp(118px,14vw,182px);height:auto;image-rendering:pixelated;filter:drop-shadow(0 16px 18px rgba(0,0,0,.5));z-index:2}
.player-mon-wrap{left:calc(50% - 100px)}
.enemy-mon-wrap{left:calc(50% - 100px)}
.player-mon{transform:scaleX(-1);transform-origin:center bottom}
.mon-shadow{position:absolute;bottom:-4px;left:50%;width:70%;height:14px;border-radius:50%;background:rgba(0,0,0,.38);filter:blur(6px);transform:translateX(-50%)}
.trainer-sprite{position:absolute;left:4%;bottom:122px;width:70px;image-rendering:pixelated;opacity:.72;filter:drop-shadow(0 10px 8px rgba(0,0,0,.4));transform:scaleX(-1)}
.trainer-shadow{position:absolute;left:6%;bottom:116px;width:80px;height:15px;background:rgba(0,0,0,.32);border-radius:50%;filter:blur(7px)}
.combatant-panel{
  position:relative;z-index:4;width:min(330px,96%);padding:9px 12px 10px;border-radius:12px;
  background:linear-gradient(180deg,rgba(12,29,23,.82),rgba(8,20,15,.9));
  border:1px solid rgba(219,228,200,.14);box-shadow:0 14px 30px rgba(0,0,0,.3),inset 0 1px 0 rgba(255,255,255,.05);
  backdrop-filter:blur(10px);
}
.enemy-panel{border-color:rgba(230,170,160,.18)}
.combatant-name-row{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:5px}
.combatant-name-row>div:first-child{display:flex;align-items:baseline;gap:7px}
#player-name,#enemy-name{font-size:15px;font-weight:600;letter-spacing:.01em}
.combatant-level{font-size:9px;color:var(--muted);letter-spacing:.06em}
.hp-track{position:relative;height:9px;border-radius:5px;background:rgba(0,0,0,.5);border:1px solid rgba(255,255,255,.08);overflow:hidden}
.hp-track.large{height:11px}
.hp-fill{height:100%;width:100%;border-radius:4px;background:linear-gradient(90deg,#4c9a65,#80cf95);transition:width .35s cubic-bezier(.2,.7,.3,1),background .3s}
.hp-fill.low{background:linear-gradient(90deg,#a34636,#d66652)}
.enemy-hp-fill{background:linear-gradient(90deg,#a84b43,#dd7161)}
.hp-text{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:8px;font-weight:600;letter-spacing:.08em;color:rgba(255,255,255,.9);text-shadow:0 1px 2px rgba(0,0,0,.7);font-variant-numeric:tabular-nums}
.block-badge{display:flex;align-items:center;gap:3px;padding:2px 6px;border-radius:5px;background:rgba(112,170,208,.15);border:1px solid rgba(126,186,224,.35);color:#b6dcf4;font-size:10px}
.block-badge span{font-size:8px}
.status-row{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px;min-height:0}
.status-pill{display:flex;align-items:center;gap:3px;font-size:8px;letter-spacing:.04em;text-transform:uppercase;padding:2px 5px;border-radius:4px;border:1px solid rgba(255,255,255,.09);background:rgba(0,0,0,.25);color:var(--cream-dim)}
.status-pill b{font-size:9px;color:#fff}
.status-pill.poison{color:#d2a7e4;border-color:rgba(169,113,184,.35)}
.status-pill.burn{color:#f2b38d;border-color:rgba(231,123,75,.35)}
.status-pill.weak{color:#c4c4c4}
.status-pill.vulnerable{color:#f0b9b0;border-color:rgba(216,98,88,.35)}
.status-pill.strength{color:#f3d48d;border-color:rgba(217,183,109,.35)}
.intent-card{
  position:absolute;top:2px;left:50%;transform:translateX(-50%);
  display:flex;align-items:center;gap:8px;padding:5px 10px 5px 6px;border-radius:10px;
  background:rgba(8,20,15,.78);border:1px solid rgba(216,98,88,.32);box-shadow:0 6px 20px rgba(0,0,0,.3);z-index:5;
  min-width:104px;
}
.intent-card.buff{border-color:rgba(217,183,109,.35)}
.intent-card.defend{border-color:rgba(112,170,208,.35)}
.intent-card.debuff{border-color:rgba(177,129,210,.35)}
.intent-icon{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:rgba(216,98,88,.15);color:#f2aaa2;font-size:14px}
.intent-card.buff .intent-icon{background:rgba(217,183,109,.12);color:var(--gold-2)}
.intent-card.defend .intent-icon{background:rgba(112,170,208,.12);color:#a8d3ec}
.intent-card.debuff .intent-icon{background:rgba(177,129,210,.12);color:#dab4ec}
.intent-copy{display:flex;flex-direction:column;line-height:1.1}
.intent-copy span{font-size:7px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}
.intent-copy b{font-size:14px;color:var(--cream)}
.intent-card .intent-name{font-size:8px;color:var(--muted);letter-spacing:.03em;max-width:80px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.stage-center{position:absolute;left:50%;top:48%;transform:translate(-50%,-50%);display:flex;flex-direction:column;align-items:center;gap:8px;opacity:.35}
.stage-rune{color:var(--gold);font-size:16px;animation:runePulse 3s ease-in-out infinite}
.stage-line{width:1px;height:70px;background:linear-gradient(180deg,transparent,rgba(217,183,109,.5),transparent)}
@keyframes runePulse{0%,100%{opacity:.35;transform:rotate(0)}50%{opacity:.8;transform:rotate(180deg)}}
