.deck-grid .card-selectable:hover{z-index:4}
.boss-fight .battle-bg{filter:saturate(.72) hue-rotate(16deg) brightness(.84)}
.boss-fight .enemy-panel{border-color:rgba(177,129,210,.32);box-shadow:0 0 34px rgba(177,129,210,.13),inset 0 1px 0 rgba(255,255,255,.06)}
.boss-fight .enemy-mon{filter:drop-shadow(0 0 22px rgba(177,129,210,.28)) drop-shadow(0 16px 18px rgba(0,0,0,.5))}
.boss-fight .platform-enemy{box-shadow:0 0 50px rgba(177,129,210,.2)}
.boss-fight .battle-moon{background:radial-gradient(circle at 40% 35%,rgba(218,190,240,.65),rgba(177,129,210,.18) 60%,transparent 70%)}
