.camp-option.used{opacity:.42;filter:grayscale(.4)}
.camp-option.used:hover{transform:none;border-color:rgba(217,183,109,.16);background:linear-gradient(150deg,rgba(28,55,42,.82),rgba(11,27,20,.9));box-shadow:0 10px 28px rgba(0,0,0,.18)}
.release-wrap{max-width:100%}
.release-grid{display:flex;justify-content:center;gap:7px;flex-wrap:wrap}
.card-preview{cursor:default}
.card-preview:hover{transform:none;box-shadow:0 10px 22px rgba(0,0,0,.34)}
.deck-grid .card-preview:hover{transform:none}
.card.reward-card.card-preview:hover{transform:none}
.hand .card{transition:transform .2s cubic-bezier(.2,.8,.2,1),box-shadow .2s,border-color .2s,filter .2s}
