684:.overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(2,8,6,.74);backdrop-filter:blur(9px);animation:overlayIn .22s ease both;overflow:auto}
686:.modal{position:relative;width:min(760px,96vw);max-height:92dvh;overflow:auto;background:linear-gradient(165deg,#1a372b 0%,#0e2119 55%,#0a1913 100%);border:1px solid rgba(217,183,109,.28);border-radius:18px;box-shadow:0 40px 100px rgba(0,0,0,.65),inset 0 1px 0 rgba(255,255,255,.07);padding:24px;animation:modalIn .3s cubic-bezier(.2,.8,.2,1) both;scrollbar-width:thin;scrollbar-color:#3a5b49 transparent}
687:.modal::-webkit-scrollbar{width:6px}.modal::-webkit-scrollbar-thumb{background:#3a5b49;border-radius:3px}
689:.modal::before{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;background:radial-gradient(ellipse at 50% 0%,rgba(217,183,109,.09),transparent 38%)}
690:.modal-close{position:absolute;top:12px;right:12px;z-index:3;width:30px;height:30px;border-radius:50%;border:1px solid rgba(255,255,255,.1);background:rgba(0,0,0,.2);color:var(--muted);font-size:16px}
691:.modal-close:hover{color:var(--cream);border-color:rgba(217,183,109,.35)}
692:.modal-head{position:relative;z-index:2;text-align:center;margin-bottom:18px}
693:.modal-head .section-kicker{justify-content:center}
694:.modal-head h2{font-size:clamp(24px,3vw,36px);margin-top:6px}
695:.modal-head p{font-size:12px;color:var(--muted);margin-top:5px}
696:.modal-actions{display:flex;justify-content:center;gap:10px;margin-top:18px;flex-wrap:wrap}
697:.modal-wide{width:min(1000px,97vw)}
698:.modal-narrow{width:min(540px,96vw)}
749:.catch-modal{width:min(660px,96vw)}
750:.catch-hero{display:flex;align-items:center;justify-content:center;gap:18px;margin:6px 0 12px}
751:.catch-hero img{width:108px;height:108px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 14px 14px rgba(0,0,0,.45));animation:catchBounce 2.4s ease-in-out infinite}
753:.catch-stars{display:flex;gap:6px;color:var(--gold);font-size:14px}
754:.catch-stars span{animation:starTwinkle 1.6s ease-in-out infinite}
755:.catch-stars span:nth-child(2){animation-delay:.3s}.catch-stars span:nth-child(3){animation-delay:.6s}
757:.catch-info{text-align:center}
758:.catch-info h2{font-size:clamp(28px,3.8vw,42px)}
759:.catch-info .catch-types{font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-top:2px}
760:.catch-card-added{display:flex;justify-content:center;margin-top:12px}
761:.catch-note{font-size:10px;color:var(--muted);text-align:center;margin-top:8px}
770:.end-screen-modal{text-align:center;width:min(640px,96vw)}
