1160:  .modal{max-height:94dvh;overflow:auto}
   Overlays, modals, tooltips, toasts
   ============================================================ */
.overlay-root{position:fixed;inset:0;z-index:100;pointer-events:none}
.overlay-root.active{pointer-events:auto}
.overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(2,8,6,.74);backdrop-filter:blur(9px);animation:overlayIn .22s ease both;overflow:auto}
@keyframes overlayIn{from{opacity:0}to{opacity:1}}
.modal{position:relative;width:min(760px,96vw);max-height:92dvh;overflow:auto;background:linear-gradient(165deg,#1a372b 0%,#0e2119 55%,#0a1913 100%);border:1px solid rgba(217,183,109,.28);border-radius:18px;box-shadow:0 40px 100px rgba(0,0,0,.65),inset 0 1px 0 rgba(255,255,255,.07);padding:24px;animation:modalIn .3s cubic-bezier(.2,.8,.2,1) both;scrollbar-width:thin;scrollbar-color:#3a5b49 transparent}
.modal::-webkit-scrollbar{width:6px}.modal::-webkit-scrollbar-thumb{background:#3a5b49;border-radius:3px}
@keyframes modalIn{from{opacity:0;transform:translateY(18px) scale(.985)}to{opacity:1;transform:none}}
.modal::before{content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;background:radial-gradient(ellipse at 50% 0%,rgba(217,183,109,.09),transparent 38%)}
.modal-close{position:absolute;top:12px;right:12px;z-index:3;width:30px;height:30px;border-radius:50%;border:1px solid rgba(255,255,255,.1);background:rgba(0,0,0,.2);color:var(--muted);font-size:16px}
.modal-close:hover{color:var(--cream);border-color:rgba(217,183,109,.35)}
.modal-head{position:relative;z-index:2;text-align:center;margin-bottom:18px}
.modal-head .section-kicker{justify-content:center}
.modal-head h2{font-size:clamp(24px,3vw,36px);margin-top:6px}
.modal-head p{font-size:12px;color:var(--muted);margin-top:5px}
.modal-actions{display:flex;justify-content:center;gap:10px;margin-top:18px;flex-wrap:wrap}
.modal-wide{width:min(1000px,97vw)}
.modal-narrow{width:min(540px,96vw)}
.overlay-title{font-family:'Cinzel',serif;font-size:clamp(30px,4vw,48px);line-height:1.1;color:var(--cream)}
.overlay-gold{color:var(--gold-2)}
.reward-summary{display:flex;justify-content:center;gap:18px;margin:12px 0 18px;font-size:12px;color:var(--muted)}
.reward-summary b{color:var(--gold-2);font-size:16px;margin-left:3px}
.reward-cards{display:flex;justify-content:center;gap:12px;flex-wrap:wrap;padding:10px 0}
.reward-cards .card{width:148px;height:207px}
.reward-cards .card:hover{transform:translateY(-12px) scale(1.035)}
.reward-skip{margin-top:8px;text-align:center}
.card-choice-label{font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);text-align:center;margin-top:2px}
.relic-pick-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:12px 0}
.relic-pick{display:flex;flex-direction:column;align-items:center;gap:6px;padding:15px 10px;border-radius:10px;border:1px solid rgba(217,183,109,.18);background:rgba(10,25,19,.65);text-align:center;transition:.2s}
.relic-pick:hover{transform:translateY(-3px);border-color:rgba(217,183,109,.5);background:rgba(26,54,42,.8)}
.relic-pick .relic-glyph{width:42px;height:42px;font-size:21px}
.relic-pick b{font-size:11px;color:var(--cream)}.relic-pick small{font-size:8px;color:var(--muted);line-height:1.3}

/* starter select */
.starter-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.starter-card{position:relative;padding:16px 14px 14px;border-radius:14px;border:1px solid rgba(255,255,255,.1);background:linear-gradient(170deg,rgba(34,66,51,.72),rgba(9,23,17,.92));text-align:center;transition:.2s;overflow:hidden}
.starter-card::before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 50% 18%,color-mix(in srgb,var(--sc) 26%,transparent),transparent 55%);opacity:.9}
.starter-card:hover{transform:translateY(-4px);border-color:color-mix(in srgb,var(--sc) 65%,#fff 10%);box-shadow:0 18px 38px rgba(0,0,0,.32),0 0 28px color-mix(in srgb,var(--sc) 18%,transparent)}
.starter-card img{position:relative;width:82px;height:82px;object-fit:contain;margin:0 auto 6px;image-rendering:pixelated;filter:drop-shadow(0 10px 10px rgba(0,0,0,.4));animation:bob 4s ease-in-out infinite}
.starter-card:nth-child(2) img{animation-delay:.4s}.starter-card:nth-child(3) img{animation-delay:.8s}
.starter-card h3{position:relative;font-family:'Cinzel',serif;font-size:21px;margin-bottom:2px}
.starter-card .starter-type{position:relative;font-size:8px;letter-spacing:.13em;text-transform:uppercase;color:var(--muted);margin-bottom:8px}
.starter-card .starter-style{position:relative;display:inline-block;padding:3px 8px;border-radius:999px;font-size:8px;letter-spacing:.09em;text-transform:uppercase;color:var(--sc);border:1px solid color-mix(in srgb,var(--sc) 40%,transparent);background:color-mix(in srgb,var(--sc) 10%,transparent);margin-bottom:8px}
.starter-card p{position:relative;font-size:9.5px;line-height:1.45;color:var(--muted);min-height:42px}
.starter-card .starter-deck{position:relative;margin-top:8px;padding-top:8px;border-top:1px solid rgba(255,255,255,.08);font-size:8px;color:var(--muted-2);line-height:1.4}
.starter-card .starter-pick{position:relative;margin-top:10px;width:100%;justify-content:center}
.starter-hp{position:relative;display:flex;justify-content:center;gap:12px;font-size:9px;color:var(--muted);margin-top:4px}
.starter-hp b{color:var(--cream)}

/* deck / party modals */
.deck-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(108px,1fr));gap:8px;padding:4px 2px 8px;max-height:55vh;overflow:auto}
.deck-tabs{display:flex;justify-content:center;gap:6px;margin-bottom:12px}
.deck-tab{padding:6px 14px;border-radius:999px;border:1px solid var(--line);font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);background:rgba(8,20,15,.4)}
.deck-tab.active{color:#241b0b;background:linear-gradient(180deg,#e8d19a,#cda75c);border-color:#f1dfaf}
.deck-summary{text-align:center;font-size:10px;color:var(--muted);margin-bottom:8px}
.party-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;max-height:58vh;overflow:auto;padding:3px}
.party-card{display:flex;gap:10px;align-items:center;padding:10px;border-radius:10px;border:1px solid rgba(255,255,255,.08);background:rgba(10,25,19,.55)}
.party-card img{width:48px;height:48px;object-fit:contain;image-rendering:pixelated}
.party-card b{font-size:12px;display:block}
.party-card small{font-size:8px;color:var(--muted);display:block;line-height:1.3}
.party-card .party-card-tag{font-size:7px;letter-spacing:.1em;text-transform:uppercase;color:var(--gold);margin-top:2px;display:inline-block}
.party-card.empty{border-style:dashed;justify-content:center;color:var(--muted-2);font-size:10px;min-height:70px}
.relic-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:8px}
.relic-detail{display:flex;gap:10px;align-items:flex-start;padding:10px;border-radius:9px;border:1px solid rgba(255,255,255,.07);background:rgba(10,25,19,.5)}
.relic-detail .relic-glyph{width:38px;height:38px;flex:0 0 auto;font-size:19px}
.relic-detail b{font-size:11px;display:block}.relic-detail small{font-size:8.5px;color:var(--muted);line-height:1.35;display:block;margin-top:2px}

/* catch */
.catch-modal{width:min(660px,96vw)}
.catch-hero{display:flex;align-items:center;justify-content:center;gap:18px;margin:6px 0 12px}
.catch-hero img{width:108px;height:108px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 14px 14px rgba(0,0,0,.45));animation:catchBounce 2.4s ease-in-out infinite}
@keyframes catchBounce{0%,100%{transform:translateY(0)}50%{transform:translateY(-8px)}}
.catch-stars{display:flex;gap:6px;color:var(--gold);font-size:14px}
.catch-stars span{animation:starTwinkle 1.6s ease-in-out infinite}
.catch-stars span:nth-child(2){animation-delay:.3s}.catch-stars span:nth-child(3){animation-delay:.6s}
@keyframes starTwinkle{0%,100%{opacity:.35;transform:scale(.8)}50%{opacity:1;transform:scale(1.15)}}
.catch-info{text-align:center}
.catch-info h2{font-size:clamp(28px,3.8vw,42px)}
.catch-info .catch-types{font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-top:2px}
.catch-card-added{display:flex;justify-content:center;margin-top:12px}

