/* ============================================================
   Phone battle layout — horizontal hand, full-height stage
   ============================================================ */
@media (max-width:760px){
  .battle-screen{justify-content:flex-start}
  .battle-stage{max-height:none}
  .hand-zone{position:relative}
  .hand{
    justify-content:flex-start;overflow-x:auto;overflow-y:hidden;
    scroll-snap-type:x proximity;scroll-padding-inline:4px;
    touch-action:pan-x;overscroll-behavior-x:contain;
  }
  .hand .card{scroll-snap-align:center;margin-left:0}
  .hand-zone.can-scroll::after,
  .hand-zone.can-scroll-left::before{
    content:"";position:absolute;top:0;bottom:0;width:26px;pointer-events:none;z-index:7;
  }
  .hand-zone.can-scroll::after,
  .hand-zone.can-scroll-left::before{
    display:flex;align-items:center;color:var(--gold-2);font-size:20px;font-weight:600;
  }
  .hand-zone.can-scroll::after{right:44px;content:"›";justify-content:flex-end;padding-right:2px;background:linear-gradient(90deg,transparent,rgba(7,16,13,.82))}
  .hand-zone.can-scroll-left::before{left:44px;content:"‹";justify-content:flex-start;padding-left:2px;background:linear-gradient(270deg,transparent,rgba(7,16,13,.82))}
}
